package net.battlehub.hub;

import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import net.battlehub.BattleHub;
import net.battlehub.arch.mod.Library;
import net.battlehub.arch.town.HungerMap;
import net.battlehub.arch.town.LobbyThemes;
import net.battlehub.arena.Blueprint;
import net.battlehub.arena.Build;
import net.battlehub.config.ConfigManager;
import net.battlehub.config.HubConfig;
import net.minecraft.world.level.block.state.BlockState;

/**
 * The Hunger Games city of this week: generated by the lobby generator from a seed of the week (the lobby's own
 * seed and size), kept until the week is over, and turned into a blueprint in the theme of each match. The layout is
 * the same in every theme; only the materials change.
 */
public final class HungerMaps {
	private HungerMaps() {}

	private static HungerMap map;
	private static String week;

	/** The map of this week (generated the first time it is asked for in a week). */
	public static synchronized HungerMap current() {
		LocalDate today = LocalDate.now();
		String w = HungerMap.weekLabel(today);
		if (map == null || !w.equals(week)) {
			HubConfig.Lobby cfg = ConfigManager.config().lobby;
			ArchMaterials.prepare(cfg.discoverModBlocks);
			long t0 = System.nanoTime();
			map = HungerMap.generate(HungerMap.weekSeed(cfg.seed, today), cfg.islandRadius, cfg.detail, cfg.townDensity, Library.defaults());
			week = w;
			BattleHub.LOGGER.info("Hunger Games: the city of week {} generated in {} ms: {} chests in the houses, {} in the landmarks, {} in the cornucopia, {} doors taken out",
					w, (System.nanoTime() - t0) / 1_000_000, map.houseChests.size(), map.landmarkChests.size(), map.cornucopia.size(), map.doorsRemoved);
		}
		return map;
	}

	/** "2026-W43": the week of the current map. */
	public static synchronized String week() {
		current();
		return week;
	}

	/** Generates this week's map now, so the first match of the week does not wait for it. */
	public static void warm() {
		try {
			current();
		} catch (RuntimeException e) {
			BattleHub.LOGGER.error("Hunger Games: could not generate this week's city", e);
		}
	}

	/** The map as a blueprint in a theme: the same blocks in the same places, in the theme's materials. */
	public static Blueprint blueprint(HungerMap m, String theme) {
		String t = LobbyThemes.supports(theme) ? theme : "castle";
		Map<String, Optional<BlockState>> states = new HashMap<>();
		Blueprint bp = new Blueprint();
		m.voxels.forEach((x, y, z, id) -> {
			if (id.equals("air")) return;
			states.computeIfAbsent(id, k -> Optional.ofNullable(state(k, t))).ifPresent(st -> bp.set(x, y, z, st));
		});
		for (HungerMap.Spot c : m.houseChests) bp.mark("chest", c.x(), c.y(), c.z());
		for (HungerMap.Spot c : m.landmarkChests) bp.mark("landmark_chest", c.x(), c.y(), c.z());
		for (HungerMap.Spot c : m.cornucopia) bp.mark("cornucopia", c.x(), c.y(), c.z());
		for (HungerMap.Spot s : m.spawns) {
			// facing the cornucopia
			bp.spawn(s.x() + 0.5, s.y(), s.z() + 0.5, (float) Math.toDegrees(Math.atan2(s.x(), -s.z())));
		}
		bp.spectator(0.5, 30, 34.5, 180, 40);
		bp.radius(m.radius + 30);
		// the lowest ground of the island is a few blocks below the plaza; who falls off the cliffs is out
		bp.voidY(-25);
		bp.playArea(Blueprint.circle(m.radius + 10), 60);
		return bp;
	}

	private static BlockState state(String id, String theme) {
		String themed = LobbyThemes.block(id, theme);
		if (themed.equals("air")) return null;
		BlockState st = Build.s(themed);
		// a block this version does not know: as it was
		if (st.isAir()) st = Build.s(id);
		return st.isAir() ? null : st;
	}
}
